e"]={}},[52]={["id"]=6585,["title"]="The Test of Skulls, Axtroz",["req"]=55,["level"]=55,["side"]="horde",["goal"]="Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["rewardLayoutUnknown"]=true,["prerequisites"]={6584},["needsId"]=6584,["from"]="Emberstrife",["startAt"]={["map"]=1445,["x"]=56.2,["y"]=88,["place"]="Dustwallow Marsh"},["turnIn"]="Emberstrife",["turnInAt"]={["map"]=1445,["x"]=56.2,["y"]=88,["place"]="Dustwallow Marsh"},["choice"]={}},[53]={["id"]=6601,["title"]="Ascension...",["req"]=55,["level"]=55,["side"]="horde",["goal"]="It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["rewardLayoutUnknown"]=true,["prerequisites"]={6585},["needsId"]=6585,["from"]="Emberstrife",["startAt"]={["map"]=1445,["x"]=56.2,["y"]=88,["place"]="Dustwallow Marsh"},["turnIn"]="Rexxar",["turnInAt"]={["place"]="Feralas"},["choice"]={}},[54]={["id"]=6602,["title"]="Blood of the Black Dragon Champion",["req"]=55,["level"]=55,["side"]="horde",["goal"]="Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar.",["note"]="Part of the Onyxia attunement.",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["rewardLayoutUnknown"]=true,["prerequisites"]={6601},["needsId"]=6601,["from"]="Rexxar",["startAt"]={["map"]=1444,["x"]=44.8,["y"]=7.4,["place"]="Desolace"},["turnIn"]="Rexxar",["turnInAt"]={["map"]=1444,["x"]=44.8,["y"]=7.4,["place"]="Desolace"},["choice"]={{["id"]=16309,["name"]="Drakefire Amulet"}}},[55]={["id"]=7761,["title"]="Blackhand's Command",["req"]=55,["level"]=55,["side"]="both",["goal"]="Find the brand that General Drakkisath guards and gain the Mark of Drakkisath, so you can use the Orb of Command.",["note"]="The Scarshield Quartermaster is in the hallway outside the Spire portal. Touch Drakkisath's Brand behind General Drakkisath; this unlocks the Orb of Command shortcut to Blackwing Lair.",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["rewardLayoutUnknown"]=true,["startAt"]={["place"]="Blackhand's Command (letter from the Scarshield Quartermaster, Blackrock Mountain)"},["turnIn"]="Drakkisath's Brand",["turnInAt"]={["place"]="Upper Blackrock Spire"},["choice"]={}},["min"]=55,["max"]=60},{["slug"]="dire-maul",["name"]="Dire Maul",["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["foreverLive"]=true,["alliance"]={},["horde"]={},[1]={["id"]=5526,["title"]="Shards of the Felvine",["req"]=56,["level"]=56,["side"]="both",["goal"]="Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.",["note"]="Kill Alzzin the Wildshaper, pick up a Felvine Shard near the vine and seal it in the Reliquary of Purity.",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["rewardLayoutUnknown"]=true,["prerequisites"]={5527},["needsId"]=5527,["from"]="Rabine Saturna",["startAt"]={["map"]=1450,["x"]=51.6,["y"]=44.4,["place"]="Nighthaven, Moonglade"},["turnIn"]="Rabine Saturna",["turnInAt"]={["map"]=1450,["x"]=51.6,["y"]=44.4,["place"]="Nighthaven, Moonglade"},["choice"]={{["id"]=18535,["name"]="Milli's Shield"},{["id"]=18536,["name"]="Milli's Lexicon"}}},[2]={["id"]=5527,["title"]="A Reliquary of Purity",["req"]=56,["level"]=56,["side"]="both",["goal"]="Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["rewardLayoutUnknown"]=true,["from"]="Rabine Saturna",["startAt"]={["map"]=1450,["x"]=51.6,["y"]=44.4,["place"]="Moonglade"},["turnIn"]="Rabine Saturna",["turnInAt"]={["map"]=1450,["x"]=51.6,["y"]=44.4,["place"]="Moonglade"},["choice"]={}},[3]={["id"]=7441,["title"]="Pusillin and the Elder Azj'Tordin",["req"]=54,["level"]=54,["side"]="both",["goal"]="Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary. Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.",["note"]="Chase and talk to Pusillin through the wing until he fights, then kill him for the book. He also drops the Crescent Key.",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["rewardLayoutUnknown"]=true,["from"]="Azj'Tordin",["startAt"]={["map"]=1444,["x"]=76.8,["y"]=37.4,["place"]="Lariss Pavilion, Feralas"},["turnIn"]="Azj'Tordin",["turnInAt"]={["map"]=1444,["x"]=76.8,["y"]=37.4,["place"]="Lariss Pavilion, Feralas"},["choice"]={{["id"]=18411,["name"]="Spry Boots"},{["id"]=18410,["name"]="Sprinter's Sword"}}},[4]={["id"]=7463,["title"]="Arcane Refreshment",["req"]=60,["level"]=60,["side"]="both",["goal"]="Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.",["note"]="Mage class quest. Lydros is in the Athenaeum (North/West); Hydrospawn Essence drops from Hydrospawn in East. Rewards Conjure Water (Rank 7).",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["class"]="MAGE",["rewardLayoutUnknown"]=true,["from"]="Lorekeeper Lydros",["startAt"]={["place"]="Dire Maul"},["turnIn"]="Lorekeeper Lydros",["turnInAt"]={["place"]="Dire Maul"},["choice"]={}},[5]={["id"]=7488,["title"]="Lethtendris's Web",["req"]=54,["level"]=54,["side"]="alliance",["goal"]="Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.",["note"]="The web drops from Lethtendris.\n\nOptional introductory quest:",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["rewardLayoutUnknown"]=true,["from"]="Latronicus Moonspear",["startAt"]={["map"]=1444,["x"]=30.4,["y"]=46,["place"]="Feathermoon Stronghold, Feralas"},["turnIn"]="Latronicus Moonspear",["turnInAt"]={["map"]=1444,["x"]=30.4,["y"]=46,["place"]="Feathermoon Stronghold, Feralas"},["choice"]={{["id"]=18491,["name"]="Lorespinner"}}},[6]={["id"]=7489,["title"]="Lethtendris's Web",["req"]=54,["level"]=54,["side"]="horde",["goal"]="Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.",["note"]="The web drops from Lethtendris.\n\nOptional introductory quest:",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d792d6824cc1e28856a555104b4d5500",["rewardLayoutUnknown"]=true,["from"]="Talo Thornhoof",["startAt"]={["map"]=1444,["x"]=76,["y"]=43.8,["place"]="Camp Mojache, Feralas"},["turnIn"]="Talo Thornhoof",["turnInAt"]={["map"]=1444,["x"]=76,["y"]=43.8,["place"]="Camp Mojache, Feralas"},["choice"]={{["id"]=18491,["name"]="Lorespinner"}}},[7]={["id"]=7492,["title"]="Camp Mojache",["req"]=54,["level"]=54,["side"]="horde",["goal"]="Speak with Talo Thornhoof at Camp Mojache in Feralas.",["note"]="Introductory step leading to Lethtendris's Web.\n\nOPTIONAL, not required",["foreverLive"]=true,["source"]="Spyglass Forever MIT",["revision"]="e0752c03d79